"use client";

import { lazy, Suspense, useSyncExternalStore } from "react";

const emptySubscribe = () => () => undefined;

const Scene = lazy(() => import("./scene"));

/** Wire a route to this file after install. WebGL loads only in the browser. */
export default function ChatCardPage() {
  const mounted = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );
  if (!mounted) {
    return <div className="h-dvh w-full bg-background" />;
  }
  return (
    <Suspense fallback={<div className="h-dvh w-full bg-background" />}>
      <Scene />
    </Suspense>
  );
}

"use client";

import { OrbitControls } from "@react-three/drei";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { IfInSessionMode, useXR, XR } from "@react-three/xr";
import { useCallback, useRef, useState } from "react";
import type { Group } from "three";
import {
  type CardSize,
  cardMeters,
  placeAtGaze,
  WorldCard,
  WorldThemeProvider,
} from "@/components/ui/world-card";
import { ChatCardBody } from "./chat-body";
import { EnterXr } from "./enter-xr";
import { ORB_RADIUS, SpeakingOrb } from "./speaking-orb";
import { xrStore } from "./xr-store";

const CHAT_CARD = {
  w: 340,
  h: 520,
  minW: 280,
  minH: 400,
  maxW: 800,
  maxH: 720,
};
const ORB_LIFT = 0.08;

function appearanceFromDom(): "light" | "dark" {
  if (typeof document === "undefined") {
    return "dark";
  }
  return document.documentElement.classList.contains("dark") ? "dark" : "light";
}

function ChatDock() {
  const session = useXR((s) => s.session);
  const camera = useThree((s) => s.camera);
  const [open, setOpen] = useState(true);
  const [size, setSize] = useState<CardSize>({
    w: CHAT_CARD.w,
    h: CHAT_CARD.h,
  });
  const meters = cardMeters(size);
  const orbTop = meters.h / 2 + ORB_LIFT;
  const orbLift = useRef(0);
  const orbSlot = useRef<Group>(null);
  const dragging = useRef(false);
  const anchor = useRef<Group>(null);
  const placed = useRef(false);

  const bringHere = useCallback(() => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    placeAtGaze(a, camera, {
      distance: 0.55,
      drop: 0.1,
      side: 0.22,
      face: true,
    });
    placed.current = true;
  }, [camera]);

  useFrame((_, dt) => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    if (session && !placed.current) {
      bringHere();
    }
    if (!session) {
      placed.current = false;
      a.position.set(0, 0, 0);
      a.rotation.set(0, 0, 0);
    }
    const orbGoal = open ? orbTop : 0;
    orbLift.current += (orbGoal - orbLift.current) * Math.min(1, 10 * dt);
    if (orbSlot.current) {
      orbSlot.current.position.y = orbLift.current;
    }
  });

  const toggleCard = () => {
    if (dragging.current) {
      return;
    }
    setOpen((value) => !value);
  };

  return (
    <WorldCard
      ref={anchor}
      limits={CHAT_CARD}
      movable
      onDragEnd={() => {
        dragging.current = false;
      }}
      onDragStart={() => {
        dragging.current = true;
      }}
      onSizeChange={setSize}
      radius={ORB_RADIUS}
      resizable={open}
      shape={open ? "card" : "orb"}
      size={size}
    >
      <group ref={orbSlot}>
        <SpeakingOrb onClick={toggleCard} />
      </group>
      {open ? <ChatCardBody height={size.h} width={size.w} /> : null}
    </WorldCard>
  );
}

export default function ChatCardScene() {
  const appearance = appearanceFromDom();
  const studio = appearance === "dark" ? "#1a1d21" : "#eeeff1";

  return (
    <div className="relative h-dvh w-full bg-background">
      <EnterXr />
      <Canvas
        camera={{ position: [0, 0, 0.85], fov: 50, near: 0.01, far: 50 }}
        gl={{ antialias: true, alpha: true }}
        style={{ position: "absolute", inset: 0 }}
      >
        <XR store={xrStore}>
          <color attach="background" args={[studio]} />
          <hemisphereLight args={[0xffffff, 0xb8bcc2, 0.95]} />
          <directionalLight intensity={1.35} position={[0.55, 1.1, 0.45]} />
          <WorldThemeProvider appearance={appearance}>
            <ChatDock />
          </WorldThemeProvider>
          <IfInSessionMode deny={["immersive-ar", "immersive-vr"]}>
            <OrbitControls enableDamping makeDefault />
          </IfInSessionMode>
        </XR>
      </Canvas>
    </div>
  );
}

import { createXRStore } from "@react-three/xr";

export const xrStore = createXRStore({
  foveation: 0.5,
  offerSession: false,
  bounded: true,
  hitTest: false,
  domOverlay: false,
  anchors: false,
  meshDetection: false,
  planeDetection: false,
  depthSensing: false,
  bodyTracking: false,
  handTracking: true,
});

export function enterAR() {
  return xrStore.enterAR();
}

export function enterVR() {
  return xrStore.enterVR();
}

"use client";

import { Container, Input, Text } from "@react-three/uikit";
import { ChevronDown, Send } from "@react-three/uikit-lucide";
import { type ReactNode, useRef, useState } from "react";
import { toolTitle } from "@/components/ui/tool";
import { splitWorkedParts, workedLabel } from "@/components/ui/worked";
import { useWorldTheme } from "@/components/ui/world-card";
import {
  type CardMessage,
  type CardPart,
  INITIAL_MESSAGES,
} from "./mock-messages";

function asciiSafe(value: string) {
  return value.replace(/[^\u0020-\u007e]/g, "?");
}

function XrReasoning({ text }: { text: string }) {
  const [open, setOpen] = useState(false);
  const theme = useWorldTheme();
  return (
    <Container width="100%" flexShrink={0} flexDirection="column" gap={2}>
      <Container
        flexDirection="row"
        alignItems="center"
        gap={4}
        onClick={() => setOpen((value) => !value)}
      >
        <ChevronDown
          color={theme.subtle}
          height={12}
          transformRotateZ={open ? 0 : 90}
          width={12}
        />
        <Text color={theme.subtle} fontSize={12}>
          Reasoning
        </Text>
      </Container>
      {open ? (
        <Text color={theme.subtle} fontSize={12}>
          {asciiSafe(text)}
        </Text>
      ) : null}
    </Container>
  );
}

function XrWorked({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const theme = useWorldTheme();
  return (
    <Container width="100%" flexShrink={0} flexDirection="column" gap={4}>
      <Container
        flexDirection="row"
        alignItems="center"
        gap={4}
        onClick={() => setOpen((value) => !value)}
      >
        <ChevronDown
          color={theme.subtle}
          height={12}
          transformRotateZ={open ? 0 : 90}
          width={12}
        />
        <Text color={theme.subtle} fontSize={12}>
          {workedLabel({ isStreaming: false })}
        </Text>
      </Container>
      {open ? (
        <Container
          flexDirection="column"
          flexShrink={0}
          gap={4}
          paddingLeft={8}
        >
          {children}
        </Container>
      ) : null}
    </Container>
  );
}

function XrPart({ part }: { part: CardPart }) {
  const theme = useWorldTheme();
  if (part.type === "text" && part.text) {
    return (
      <Text color={theme.text} fontSize={13}>
        {asciiSafe(part.text)}
      </Text>
    );
  }
  if (part.type === "reasoning" && part.text) {
    return <XrReasoning text={part.text} />;
  }
  if (part.type.startsWith("tool-") || part.type === "dynamic-tool") {
    return (
      <Text color={theme.subtle} fontSize={12}>
        {asciiSafe(toolTitle(part.toolName ?? part.type, part.input))}
      </Text>
    );
  }
  return null;
}

function XrAssistantParts({ message }: { message: CardMessage }) {
  return (
    <Container flexDirection="column" flexShrink={0} gap={8} width="100%">
      {splitWorkedParts(message.parts).map((segment) => {
        if (segment.kind === "worked") {
          const start = segment.items[0]?.index ?? 0;
          return (
            <XrWorked key={`w-${start}`}>
              {segment.items.map((item) => (
                <XrPart key={item.index} part={item.part} />
              ))}
            </XrWorked>
          );
        }
        return <XrPart key={segment.item.index} part={segment.item.part} />;
      })}
    </Container>
  );
}

function XrMessageRow({ message }: { message: CardMessage }) {
  const mine = message.role === "user";
  const theme = useWorldTheme();
  const text = message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text ?? "")
    .join("\n");
  if (mine && !text) {
    return null;
  }
  return (
    <Container
      alignItems={mine ? "flex-end" : "flex-start"}
      flexDirection="column"
      flexShrink={0}
      width="100%"
    >
      {mine ? (
        <Container
          alignSelf="flex-end"
          backgroundColor={theme.bubble}
          borderRadius={10}
          flexShrink={0}
          maxWidth="80%"
          padding={8}
          width="auto"
        >
          <Text color={theme.text} fontSize={13}>
            {asciiSafe(text)}
          </Text>
        </Container>
      ) : (
        <Container flexShrink={0} maxWidth="100%" width="100%">
          <XrAssistantParts message={message} />
        </Container>
      )}
    </Container>
  );
}

export function ChatCardBody({
  width,
  height,
}: {
  width: number;
  height: number;
}) {
  const theme = useWorldTheme();
  const [messages, setMessages] = useState(INITIAL_MESSAGES);
  const [inputKey, setInputKey] = useState(0);
  const draft = useRef("");

  const send = () => {
    const text = draft.current.trim();
    if (!text) {
      return;
    }
    draft.current = "";
    setInputKey((key) => key + 1);
    const id = `m-${messages.length + 1}`;
    setMessages((current) => [
      ...current,
      { id: `${id}-u`, role: "user", parts: [{ type: "text", text }] },
      {
        id: `${id}-a`,
        role: "assistant",
        parts: [
          {
            type: "text",
            text: "Mocked reply. Point the transport at your API when you have one.",
          },
        ],
      },
    ]);
  };

  return (
    <Container
      backgroundColor={theme.card}
      borderRadius={12}
      flexDirection="column"
      gap={6}
      height={height}
      padding={8}
      pixelSize={0.001}
      pointerEvents="auto"
      width={width}
    >
      <Text color={theme.text} fontSize={14}>
        Assistant
      </Text>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <Container
        flexDirection="column"
        flexGrow={1}
        gap={6}
        minHeight={0}
        overflow="scroll"
        width="100%"
      >
        {messages.map((message) => (
          <XrMessageRow key={message.id} message={message} />
        ))}
      </Container>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <Container
        alignItems="center"
        flexDirection="row"
        flexShrink={0}
        gap={4}
        width="100%"
      >
        <Container
          backgroundColor={theme.muted}
          borderRadius={8}
          flexGrow={1}
          height={36}
          minWidth={0}
          paddingX={8}
        >
          <Input
            key={inputKey}
            onValueChange={(value: string) => {
              draft.current = value;
            }}
            placeholder="Ask in world space"
          />
        </Container>
        <Container onClick={send}>
          <Send color={theme.text} height={18} width={18} />
        </Container>
      </Container>
    </Container>
  );
}

"use client";

import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import type { Mesh } from "three";
import { useWorldTheme } from "@/components/ui/world-card";

export const ORB_RADIUS = 0.04;

export function SpeakingOrb({ onClick }: { onClick: () => void }) {
  const mesh = useRef<Mesh>(null);
  const theme = useWorldTheme();

  useFrame((state) => {
    const m = mesh.current;
    if (!m) {
      return;
    }
    const t = state.clock.elapsedTime;
    const s = 1 + Math.sin(t * 2.2) * 0.04;
    m.scale.setScalar(s);
  });

  return (
    <mesh ref={mesh} name="speaking-orb" onClick={onClick}>
      <icosahedronGeometry args={[ORB_RADIUS, 2]} />
      <meshStandardMaterial
        color={theme.card}
        emissive={theme.hover}
        emissiveIntensity={0.45}
        metalness={0.2}
        roughness={0.35}
      />
    </mesh>
  );
}

export type CardPart = {
  type: string;
  text?: string;
  toolName?: string;
  input?: unknown;
  output?: unknown;
};

export type CardMessage = {
  id: string;
  role: "user" | "assistant";
  parts: CardPart[];
};

export const INITIAL_MESSAGES: CardMessage[] = [
  {
    id: "u1",
    role: "user",
    parts: [{ type: "text", text: "What am I looking at?" }],
  },
  {
    id: "a1",
    role: "assistant",
    parts: [
      {
        type: "reasoning",
        text: "The wearer is in a WebXR session. I will describe the in-world card, not a 2D page.",
      },
      {
        type: "text",
        text: "You are looking at an in-world chat card. Drag the handle to move it. Pinch a corner to resize. Enter VR or AR to place it at your gaze.",
      },
    ],
  },
  {
    id: "u2",
    role: "user",
    parts: [{ type: "text", text: "Make the hole 8mm." }],
  },
  {
    id: "a2",
    role: "assistant",
    parts: [
      {
        type: "tool-cad_edit",
        toolName: "cad_edit",
        input: { feature: "hole", diameter_mm: 8 },
        output: { ok: true, diameter_mm: 8 },
      },
      {
        type: "text",
        text: "Updated the hole to 8 mm. The card stays in world space while the model rebuilds.",
      },
    ],
  },
];

"use client";

import { useEffect, useState } from "react";
import { enterAR, enterVR } from "./xr-store";

type XrSupport = { ar: boolean; vr: boolean };

export function EnterXr() {
  const [support, setSupport] = useState<XrSupport | null>(null);

  useEffect(() => {
    const xr = navigator.xr;
    if (!xr) {
      setSupport({ ar: false, vr: false });
      return;
    }
    let cancelled = false;
    Promise.all([
      xr.isSessionSupported("immersive-ar").catch(() => false),
      xr.isSessionSupported("immersive-vr").catch(() => false),
    ]).then(([ar, vr]) => {
      if (!cancelled) {
        setSupport({ ar, vr });
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  if (!(support?.ar || support?.vr)) {
    return null;
  }

  return (
    <div className="pointer-events-auto absolute right-4 bottom-4 z-10 flex gap-2 rounded-xl border border-border bg-card/95 p-1 shadow-lg">
      {support.vr ? (
        <button
          className="h-9 rounded-lg px-3 text-sm"
          onClick={() => {
            enterVR();
          }}
          type="button"
        >
          Enter VR
        </button>
      ) : null}
      {support.ar ? (
        <button
          className="h-9 rounded-lg px-3 text-sm"
          onClick={() => {
            enterAR();
          }}
          type="button"
        >
          Enter AR
        </button>
      ) : null}
    </div>
  );
}
